package com.myeshopping.invoiceservice.entity;
import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime;
@Entity @Table(name="invoices",uniqueConstraints=@UniqueConstraint(columnNames="order_id")) @Data @Builder @NoArgsConstructor @AllArgsConstructor public class Invoice { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="invoice_number",nullable=false,unique=true,length=40) private String invoiceNumber; @Column(name="order_id",nullable=false) private Long orderId; @Column(name="payment_id",nullable=false) private Long paymentId; @Column(nullable=false) private Long customerId; @Column(nullable=false) private double amount; @Column(nullable=false,length=3) private String currency; @Column(nullable=false) private LocalDateTime issuedAt; @PrePersist void prePersist(){issuedAt=LocalDateTime.now();} }
